def head_log_paths():
    return sorted({services['api'][1], *[p for p in (base / 'head/ray').rglob('worker-*') if p.is_file() and p.suffix in ('.out', '.err')]}, key=str)

def head_log_positions():
    return {str(p): p.stat().st_size for p in head_log_paths()}

def router_started_since(positions):
    marker = 'Started handler for model ' + s['config']['model']
    found = []
    for p in head_log_paths():
        assert p.resolve().is_relative_to(base.resolve())
        with p.open('rb') as stream:
            stream.seek(positions.get(str(p), 0))
            raw = stream.read((16 << 20) + 1)
        assert len(raw) <= 16 << 20
        text = raw.decode('utf-8', errors='replace')
        if 'RayTaskError' in text and 'RoundRobinRouter.start' in text:
            raise RuntimeError('Actual router.start task failed; see ' + str(p))
        for line in text.splitlines():
            clean = re.sub('\\x1b\\[[0-9;]*m', '', line)
            if re.search(re.escape(marker) + '(?=\\s|$)', clean):
                found.append({'path': str(p), 'after_offset': positions.get(str(p), 0), 'line_sha256': hashlib.sha256(line.encode()).hexdigest()})
    return found
